<script src="{{ asset('public/assets/school/js/bootstrap.bundle.min.js') }}"></script>
<script>
$(function(){
    $.ajaxSetup({headers:{'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content')}});
    function loginBusy(loading){$('#submitBtn').prop('disabled',loading).html(loading?'<span class="spinner-border spinner-border-sm"></span><span>Signing in...</span>':'<i class="bi bi-box-arrow-in-right"></i><span>Sign in securely</span>')}
    $('.password-toggle').on('click',function(){var input=$('#password'),show=input.attr('type')==='password';input.attr('type',show?'text':'password');$(this).attr({'aria-label':show?'Hide password':'Show password','aria-pressed':show?'true':'false'}).find('i').attr('class',show?'bi bi-eye-slash':'bi bi-eye')});
    $('#loginForm').on('submit',function(event){event.preventDefault();var form=$(this);$('#user_name_error,#password_error').text('');loginBusy(true);$.ajax({url:form.attr('action'),type:'POST',data:form.serialize(),success:function(response){if(response.status==='success'){window.location.href=response.redirect_url;return}loginBusy(false);$('#user_name_error').text(response.user_name_error||'');$('#password_error').text(response.password_error||'');if(response.message)StudentModal.error('Sign in failed',response.message)},error:function(xhr){loginBusy(false);var response=xhr.responseJSON||{},errors=response.errors||{};$('#user_name_error').text(errors.user_name?errors.user_name[0]:'');$('#password_error').text(errors.password?errors.password[0]:'');if(response.message)StudentModal.error('Sign in failed',response.message)}})});
    $('.mpin-input').on('input',function(){this.value=this.value.replace(/\D/g,'').slice(0,1);if(this.value)$(this).next('.mpin-input').focus();var value='';$('.mpin-input').each(function(){value+=$(this).val()});$('#final_mpin').val(value)}).on('keydown',function(event){if(event.key==='Backspace'&&!this.value)$(this).prev('.mpin-input').focus()});
    $('#mpinModal').on('shown.bs.modal',function(){$('.mpin-input').val('').first().focus();$('#final_mpin').val('')});
    $('#mpinForm').on('submit',function(event){event.preventDefault();var value=$('#final_mpin').val(),button=$('#mpinSubmitBtn');if(value.length!==4){StudentModal.error('Incomplete mPIN','Please enter all four digits.');return}button.prop('disabled',true).html('<span class="spinner-border spinner-border-sm"></span> Signing in...');$.ajax({url:@json(url('mpin-login')),type:'POST',data:{_token:$('meta[name="csrf-token"]').attr('content'),mpin:value},success:function(response){if(response.status==='success'){window.location.href=response.redirect_url}else{button.prop('disabled',false).html('<i class="bi bi-box-arrow-in-right"></i> Sign in with mPIN');StudentModal.error('mPIN login failed',response.message||'Invalid mPIN.')}},error:function(){button.prop('disabled',false).html('<i class="bi bi-box-arrow-in-right"></i> Sign in with mPIN');StudentModal.error('Unable to sign in','Server error. Please try again.')}})});
    $('#GenerateMpinModal').on('shown.bs.modal',function(){$('#mpin_user').trigger('focus')});$('#mpin_code').on('input',function(){this.value=this.value.replace(/\D/g,'').slice(0,4)});
    $('#GenerateMpinForm').on('submit',function(event){event.preventDefault();var form=this,button=$('#GenerateMpinBtn');button.prop('disabled',true).html('<span class="spinner-border spinner-border-sm"></span> Saving...');$.ajax({url:@json(url('save-mpin')),type:'POST',data:$(form).serialize(),success:function(response){button.prop('disabled',false).html('<i class="bi bi-check2-circle"></i> Save secure mPIN');if(response.status==='success'){$('#GenerateMpinModal').modal('hide');form.reset();StudentModal.success('mPIN created',response.message||'Your secure mPIN is ready.')}else StudentModal.error('Could not create mPIN',response.message||'Please check your details.')},error:function(xhr){button.prop('disabled',false).html('<i class="bi bi-check2-circle"></i> Save secure mPIN');StudentModal.error('Could not create mPIN',(xhr.responseJSON&&xhr.responseJSON.message)||'Server error. Please try again.')}})});
});
document.addEventListener('DOMContentLoaded',function(){@if(Session::has('message'))StudentModal.open({type:'success',title:'Success',message:@json(session('message')),timer:1800,showConfirm:false});@elseif(Session::has('error'))StudentModal.error('Unable to continue',@json(session('error')));@endif});
</script>
@include('layout.csrf_refresh')
